'use strict';
// Register canonical USD prices before installing the new, already-denominated world decisions.
Economy.install();WorldTimeline.install();
const EpochUI=(()=>{
 const num=n=>(Number(n)||0).toLocaleString('en-US',{maximumFractionDigits:0}),labels={housing:'ที่พัก / บำรุงถิ่น',food:'อาหารและแหล่งดำรงชีวิต',utilities:'น้ำ พลังงาน และการบำรุง',health:'สุขภาพและการดูแล',transport:'การเดินทาง',needs:'ของจำเป็น'};
 function panel(s){const e=Economy.ensure(s),w=WorldTimeline.impact(s),last=e.last;return `<section class="epoch-panels">${typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)?`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">ถิ่นที่เลี้ยงร่างของคุณ</span><strong>${Math.round(s.raceDrives.resource)} <small>/100</small></strong><span>อาหาร พลัง และจุดยึดตามรูปกาย</span><small>เงินที่เก็บไว้ ${num(s.gold)} ทอง · ดูการแลกเปลี่ยน ↗</small></button>`:`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">เงินพร้อมใช้ · 1 ทอง = 1 USD</span><strong>${num(s.gold)} <small>ทอง</small></strong><span class="${e.debt>0?'money-loss':'money-muted'}">${e.debt>0?'หนี้ '+num(e.debt)+' · ดอกเบี้ย 18% ต่อปี':last?'รายรับสุทธิช่วงล่าสุด '+num(last.gross-last.tax)+' ทอง':'เปิดบัญชีรายรับและค่าครองชีพ'}</span><small>${last?'ค่าใช้จ่ายช่วงล่าสุด '+num(last.expenses)+' ทอง':'เงินครอบครัว '+num(e.familyFund)+' ทอง'} · ดูบัญชี ↗</small></button>`}<button class="panel epoch-overview ${w.severity>.4?'epoch-danger':''}" id="openWorldYear"><span class="eyebrow">ปฏิทินโลก · ปี ${w.year}</span><strong>${esc(w.threats[0]?.name||w.omen)}</strong><span>${w.threats[0]?w.threats[0].phase==='warning'?'กำลังระดมพล · กองทัพยังไม่บุก':w.threats[0].mode==='peace'?'เจรจาแทนสงคราม':w.threats[0].mode==='delay'?'พักการระดมทัพ':'แนวรบเปิดแล้ว':w.local?'ถิ่นของคุณได้รับผลโดยตรง':'ข่าวและผลกระทบจากต่างถิ่น'}</span><small>ราคาท้องถิ่น ${Math.round(w.price*100)}% · โอกาสงาน ${Math.round(w.jobs*100)}% · ดูโลก ↗</small></button></section>`}
 function bind(){if($('#openEconomy'))$('#openEconomy').onclick=money;if($('#openWorldYear'))$('#openWorldYear').onclick=world}
 function refresh(view){save();clock.reset();render();view()}
 function money(){const s=state,e=Economy.ensure(s),q=Economy.quote(s),last=e.last,locked=s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<16;modal(`<section class="epoch-dialog"><span class="eyebrow">บัญชีชีวิต · 1 ทอง = 1 USD</span><h2>เงินพร้อมใช้ ${num(s.gold)} ทอง</h2><p class="money-explainer">ฐานค่าจ้างและราคาจำลองระดับอเมริกา อาณาจักรและเหตุการณ์โลกปรับราคาอีกชั้นหนึ่ง เงินเดินทุก 3 เดือนตามปฏิทินโลก ไม่ลดรายได้เพราะเผ่าอายุยืน</p><div class="economy-totals"><div><small>ค่าจ้างเต็มปีโดยประมาณ</small><b>${num(Economy.salary(s))}</b></div><div><small>ค่าครองชีพต่อเดือน</small><b>${num(q.monthly)}</b></div><div><small>หนี้ส่วนตัว</small><b class="money-loss">${num(e.debt)}</b></div><div><small>เงินครอบครัว</small><b>${num(e.familyFund)}</b></div></div>${e.familyArrears>0?`<p class="economy-warning">ค่าใช้จ่ายที่ครอบครัวยังขาด ${num(e.familyArrears)} ทอง · ยอดนี้แยกจากหนี้ของคุณ</p>`:''}${last?`<h3>ช่วง 3 เดือนล่าสุด · ปี ${last.year}</h3><dl class="account-lines"><div><dt>รายรับก่อนภาษี</dt><dd>+${num(last.gross)}</dd></div><div><dt>ภาษีจำลอง</dt><dd>−${num(last.tax)}</dd></div><div><dt>เงินช่วยจากบ้าน</dt><dd>+${num(last.support)}</dd></div><div><dt>ค่าใช้จ่ายรวมบิลฉุกเฉิน</dt><dd>−${num(last.expenses)}</dd></div><div><dt>ดอกเบี้ยหนี้</dt><dd>−${num(last.interest)}</dd></div><div><dt>ชำระเงินต้น</dt><dd>−${num(last.principal)}</dd></div>${last.shortfall?`<div class="money-loss"><dt>ส่วนขาดที่กลายเป็นหนี้</dt><dd>${num(last.shortfall)}</dd></div>`:''}</dl>`:''}${typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)?'<p class="money-explainer">วิถีนี้พึ่งแหล่งอาหาร พลัง และจุดยึดของถิ่น ไม่รับเงินเดือนและไม่เสียค่าเช่าหรือภาษีเมือง หนี้เดิมยังเกิดดอกเบี้ย การรับงานใช้เงินเปิดเมื่อเลือกร่วมระบบแลกเปลี่ยน</p>':''}<h3>แผนค่าครองชีพ</h3><div class="epoch-selectors"><label>รูปแบบการใช้จ่าย<select id="economyBudget" ${locked?'disabled':''}>${[['lean','ประหยัด · ลดงบ 20%'],['standard','มาตรฐาน'],['comfort','สะดวกสบาย · เพิ่มงบ 35%']].map(([id,label])=>`<option value="${id}" ${e.budget===id?'selected':''}>${label}</option>`).join('')}</select></label><label>ที่พัก<select id="economyHousing" ${locked||q.native?'disabled':''}><option value="family" ${e.housing==='family'?'selected':''}>แบ่งค่าใช้จ่ายกับครอบครัว</option><option value="rent" ${e.housing==='rent'?'selected':''}>เช่าที่พักแยก</option></select></label></div><dl class="account-lines">${q.rows.map(r=>`<div><dt>${labels[r.id]}</dt><dd>${num(r.monthly)} / เดือน</dd></div>`).join('')}</dl><p class="money-explainer">${q.native?'วิถีถิ่นเดิมไม่เสียค่าเช่าบ้านมนุษย์ แต่ยังมีค่าดูแลร่าง แหล่งเสบียง และการแลกเปลี่ยน':'การเลือกแผนมีผลเมื่อเวลาผ่านไป การประหยัดช่วยลดรายจ่าย แต่เมื่อเงินยังขาดจะกระทบกำลังและความสุข'} · ภาษีเป็นแบบจำลองเพื่อสมดุลเกม</p><h3>หาเงินและจัดการภาระ</h3><div class="choices">${Economy.actions.map(a=>`<button class="choice" data-economy-action="${a.id}" ${locked||e.actionQuarter===s.calendar.count||typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)&&['shift','aid'].includes(a.id)?'disabled':''}><span><b>${a.name}</b><small>${a.description}</small></span></button>`).join('')}</div><p id="economyError" class="money-loss" role="status"></p><p class="money-explainer">จัดการได้หนึ่งเรื่องต่อช่วง 3 เดือน รับงานเพิ่มใช้กำลังและเวลาจริง · เงินลงทุนและของที่ซื้อยังอยู่ในบัญชีใช้เงินเดิม</p><button class="secondary" id="economySpending">ใช้เงินและลงทุน →</button><details><summary>รายการที่บันทึกไว้</summary>${e.history.map(h=>`<p><b>อายุ ${h.age} · ${esc(h.title)}</b><br>${esc(h.text)}</p>`).join('')}</details></section>`);$('#economyBudget').onchange=ev=>{if(Economy.setPlan(s,'budget',ev.target.value))refresh(money)};$('#economyHousing').onchange=ev=>{if(Economy.setPlan(s,'housing',ev.target.value))refresh(money)};document.querySelectorAll('[data-economy-action]').forEach(b=>b.onclick=()=>{if(Economy.action(s,b.dataset.economyAction))refresh(money);else $('#economyError').textContent='เงื่อนไขยังไม่ครบ หรือเงินพร้อมใช้ไม่พอสำหรับรายการนี้'});$('#economySpending').onclick=SpendingUI.open}
 function offer(id){const s=state,event=EVENTS.find(e=>e.officeOnly===id);if(!event||s.dead||s.outcome||s.calendar.pending||!Engine.eligible(s,event))return;s.event={...WorldTimeline.decorate(s,event),context:WorldLore.context(s,s.calendar.count)};s.calendar.pending=true;$('#modal').close();save();render()}
 function world(){const s=state,w=WorldTimeline.ensure(s),report=WorldTimeline.impact(s),cy=WorldTimeline.cycle(s),upcoming=WorldTimeline.arcs.map(a=>({...a,due:WorldTimeline.epoch+WorldTimeline.era(s)*WorldTimeline.span+a.year+(cy>=a.year+a.duration?WorldTimeline.span:0)})).sort((a,b)=>a.due-b.due);modal(`<section class="epoch-dialog"><span class="eyebrow">พงศาวดารโลก · ปี ${report.year}</span><h2>${esc(report.omen)}</h2><p>${esc(report.news)}</p><p class="money-explainer">ทุกเผ่าในโลกจำลองนี้ใช้ปฏิทินเดียวกัน เหตุการณ์หลักเกิดตามปี แม้คุณจะไม่ได้เป็นเผ่าที่เริ่มสงคราม นโยบายของคุณเมื่อเป็นผู้นำสามารถเปลี่ยนผลของยุคนั้นได้</p><div class="epoch-chronicle">${upcoming.map(a=>{const active=report.threats.find(t=>t.id===a.id);return `<article class="${active?.phase==='active'&&active.mode==='attack'?'epoch-danger':''}"><small>ปี ${a.due} · ${a.duration} ปี</small><h3>${esc(a.name)}</h3><p>${esc(active?.phase==='warning'?a.warning:active?.mode==='peace'?'ผู้นำเลือกเจรจา เส้นทางถูกเปิดแทนการบุก':active?.mode==='delay'?'ผู้นำพักแผนรบในยุคนี้':active?a.text:a.warning)}</p><small>${esc(a.counter)}</small></article>`}).join('')}</div><h3>ผลกระทบใน 16 อาณาจักร</h3><div class="epoch-regions">${KINGDOMS.map((k,i)=>{const r=WorldTimeline.impact(s,i);return `<div class="${i===s.kingdom?'current':''}"><b>${k[0]}${i===s.kingdom?' · คุณอยู่ที่นี่':''}</b><span>ราคา ${Math.round(r.price*100)}% · งาน ${Math.round(r.jobs*100)}%</span><small>${r.severity>.5?'แนวรบและการอพยพ':r.severity>.15?'เสบียงและการค้าได้รับผล':'ผลกระทบทางอ้อม'}</small></div>`}).join('')}</div><h3>อำนาจที่เปลี่ยนโลกได้</h3>${w.office?`<p>ตำแหน่งของคุณ: <b>${esc(WorldTimeline.offices.find(o=>o.id===w.office).name)}</b></p><p>ก่อนปีบุกของฝ่ายคุณหนึ่งปี จะมีคำถามเรื่องกองทัพขึ้นและหยุดเวลารอคุณ</p>`:`<p class="money-explainer">สภารับฟังผู้ที่โตเต็มวัย มีชื่อเสียง 55 สายสัมพันธ์ 40 และกำลังหรือเวท 60 ขึ้นไป สายเลือดเปิดโอกาส แต่ไม่ได้มอบตำแหน่งให้ตั้งแต่เกิด</p><div class="choices">${WorldTimeline.offices.filter(o=>o.test(s)).map(o=>`<button class="choice" data-world-office="${o.id}" ${!WorldTimeline.eligibleOffice(s,o.id)||s.calendar.pending||s.outcome||s.dead?'disabled':''}><b>${o.name}</b><small>ชื่อเสียง ${Math.round(s.fame)}/55 · สัมพันธ์ ${Math.round(s.bond)}/40 · กำลัง/เวท ${Math.round(Math.max(s.magic,s.power))}/60 · วัยเทียบมนุษย์ 25 ปี</small></button>`).join('')}</div>`}<h3>ปีที่ผ่านมา</h3>${w.history.slice(0,12).map(h=>`<p><b>${h.year}</b> · ${esc(h.title)} · ${esc(KINGDOMS[h.realm][0])}</p>`).join('')}</section>`);document.querySelectorAll('[data-world-office]').forEach(b=>b.onclick=()=>offer(b.dataset.worldOffice))}
 return {panel,bind,money,world,offer};
})();
